test('lineVAT calculates VAT on amount after discount', () => {
  // 10 qty * 1000 unitPrice = 10000 cents
  // 10% discount = 1000 cents
  // Amount after discount = 9000 cents
  // 21% VAT = 1890 cents
  assert.equal(lineVAT({ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }), 1890);
});

test('lineVAT with no discount', () => {
  // 10 qty * 1000 unitPrice = 10000 cents
  // 0 discount
  // Amount after discount = 10000 cents
  // 21% VAT = 2100 cents
  assert.equal(lineVAT({ qty: 10, unitPrice: 1000, vatRate: 21 }), 2100);
});

test('lineVAT with 0% VAT rate', () => {
  assert.equal(lineVAT({ qty: 10, unitPrice: 1000, vatRate: 0 }), 0);
});

test('lineVAT with 9% VAT rate', () => {
  // 10 qty * 1000 unitPrice = 10000 cents
  // 9% VAT = 900 cents
  assert.equal(lineVAT({ qty: 10, unitPrice: 1000, vatRate: 9 }), 900);
});

test('lineVAT rounds to nearest cent', () => {
  // 100 qty * 33 unitPrice = 3300 cents
  // 21% VAT = 693 cents
  assert.equal(lineVAT({ qty: 100, unitPrice: 33, vatRate: 21 }), 693);
});

test('invoiceTotals with VAT returns subtotal, discount, vat, and total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 10 * 9500 = 95000
  // No discount (standard tier = 0)
  // VAT 21% = 19950
  // Total = 95000 + 19950 = 114950
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 19950);
  assert.equal(totals.total, 114950);
});

test('invoiceTotals with discount and VAT', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 10 * 9500 = 95000
  // Discount 10% = 9500
  // Amount after discount = 85500
  // VAT 21% of 85500 = 17955
  // Total = 95000 - 9500 + 17955 = 103455
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455);
});

