  assert.equal(lines[1], 'Kite & Co');
  assert.equal(lines[2], '10 × Development (hour) @ €95.00 = €950.00');
  assert.equal(lines[3], '3 × Copywriting (hour) @ €60.00 = €180.00');
  assert.equal(lines[4], '250 × Sticker sheet @ €0.50 = €125.00');
  assert.equal(lines[5], 'Subtotal: €1,255.00');
  // C-003 is silver tier, so 2.5% discount: 1255 * 0.025 = 31.375 → 31 (rounded)
  // After discount: 1255 - 31 = 1224
  // VAT 21% on each line, then sum the rounded VATs
  // DEV-HOUR VAT: 950 * 0.21 = 199.5 → 200
  // COPY-HOUR VAT: 180 * 0.21 = 37.8 → 38
  // STICKER VAT: 125 * 0.21 = 26.25 → 26
  // Total VAT: 200 + 38 + 26 = 264
  // But wait, we have tier discount applied, so:
  // After discount, each line has VAT computed on the discounted amount
  assert.equal(lines[6], 'Discount: -€0.31');
  assert.equal(lines[7], 'VAT: €2.63');
  assert.equal(lines[8], 'Total: €1,257.32');
});

