test('invoiceTotals with complex discount and VAT scenario', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 5 },
      { sku: 'STICKER', qty: 100, name: 'Sticker sheet', unitPrice: 50, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // DEV-HOUR: 10 * 9500 = 95000, discount 5% = 4750, after discount = 90250, VAT 21% = 18952.5 → 18953
  // STICKER: 100 * 50 = 5000, no discount = 5000, after discount = 5000, VAT 21% = 1050
  // Subtotal = 100000, Discount = 4750, VAT = 18953 + 1050 = 20003
  // Total = 100000 - 4750 + 20003 = 115253
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 20003);
  assert.equal(totals.total, 115253);
});

