    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 10 * 9500 = 95000
  // Discount 10% = 9500
  // Amount after discount = 85500
  // VAT 21% of 85500 = 17955
  // Total = 95000 - 9500 + 17955 = 103455
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455);
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 0 },
      { sku: 'STICKER', qty: 100, name: 'Sticker sheet', unitPrice: 50, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // DEV-HOUR: 10 * 9500 = 95000, VAT = 19950
  // STICKER: 100 * 50 = 5000, VAT = 1050
  // Total VAT = 21000
  // Total = 100000 + 21000 = 121000
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.vat, 21000);
  assert.equal(totals.total, 121000);
});

test('invoiceTotals with 0% VAT line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'BOOK', qty: 5, name: 'Book', unitPrice: 10000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Book: 5 * 10000 = 50000, VAT = 0
  assert.equal(totals.subtotal, 50000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 50000);
});

test('invoiceTotals with complex discount and VAT scenario', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 5 },
      { sku: 'STICKER', qty: 100, name: 'Sticker sheet', unitPrice: 50, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // DEV-HOUR: 10 * 9500 = 95000, discount 5% = 4750, after discount = 90250, VAT 21% = 18952.5 → 18952 (banker's rounding)
  // STICKER: 100 * 50 = 5000, no discount = 5000, after discount = 5000, VAT 21% = 1050
  // Subtotal = 100000, Discount = 4750, VAT = 18952 + 1050 = 20002
  // Total = 100000 - 4750 + 20002 = 115252
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 20002);
  assert.equal(totals.total, 115252);
});

